"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { useRef, useState, useTransition } from "react";
import { Check, Crown, LoaderCircle, Plus } from "lucide-react";
import { useRouter } from "next/navigation";
import { markReplied, undoReply } from "@/lib/recipient-actions";
import { addToShortlist } from "@/lib/actions";
import {
  useWorkspaceEntitlements,
  refreshWorkspaceAccess,
} from "@/components/workspace-quota";
import { Tooltip } from "@/components/ui/Tooltip";
import type { ActionResult } from "@/lib/errors";
import { PremiumTooltip } from "./HistoryInfoRow";
import styles from "./history.module.css";
import { cn } from "@/lib/utils";
export type ShortlistState = {
  inShortlist: boolean;
  blocked: boolean;
  active: boolean;
};
export function RowActions({
  id,
  status,
  shortlist,
}: {
  id: string;
  status: string;
  shortlist: ShortlistState;
}) {
  if (status === "CANCELLED") {
    return (
      <div className="flex justify-end">
        <Tooltip
          className="history-surface"
          content="No actions available for cancelled emails."
        >
          <span
            role="note"
            tabIndex={0}
            aria-label="No actions available for cancelled emails."
            className="inline-flex h-8.5 w-8.5 items-center justify-center rounded-full text-[var(--h-muted)]"
          >
            —
          </span>
        </Tooltip>
      </div>
    );
  }
  if (status !== "SENT" && status !== "REPLIED") return null;
  return (
    <div className={`${styles.actions} flex justify-end gap-1.5`}>
      <ReplyAction id={id} status={status} />
      <ShortlistAction id={id} shortlist={shortlist} />
    </div>
  );
}
function ReplyAction({ id, status }: { id: string; status: string }) {
  const upgrade = usePremiumUpgrade();
  const access = useWorkspaceEntitlements();
  const locked = !access.features.markReplied;
  const replied = status === "REPLIED";
  const explanation = replied ? "Replied. Click to undo" : "Mark replied";
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const busy = useRef(false);
  const router = useRouter();
  if (status !== "SENT" && !replied) return null;
  function run() {
    if (pending || busy.current) return;
    if (locked) return upgrade({ feature: "replied" });
    busy.current = true;
    setResult(undefined);
    start(async () => {
      try {
        setResult(await (replied ? undoReply(id) : markReplied(id)));
        refreshWorkspaceAccess();
        router.refresh();
      } catch {
        setResult({
          ok: false,
          message: replied
            ? "Could not undo this reply. Please try again."
            : "Could not save this change. Please try again.",
        });
      } finally {
        busy.current = false;
      }
    });
  }
  return (
    <div>
      <Tooltip
        className="history-surface"
        interactive={locked}
        content={
          locked ? (
            <PremiumTooltip actionDescription={explanation} />
          ) : (
            explanation
          )
        }
      >
        <button
          type="button"
          className={cn(
            styles.action,
            "cursor-pointer grid place-items-center w-8.5 h-8.5 p-0 border border-solid border-[var(--appearance-border,_var(--color-history-border-color-18))] rounded-[50%] relative [background:transparent] text-[var(--h-text)] css-hover:[background:var(--appearance-wash,_var(--color-history-background-22))] [&[aria-disabled='true']]:opacity-[0.5] [&[aria-disabled='true']]:cursor-default",
            locked
              ? "border-dashed"
              : replied
                ? `${styles.active} [background:var(--appearance-primary,_linear-gradient(_135deg,_var(--color-history-h-purple-13),_var(--color-history-h-pink-14)))] css-hover:[background:var(--appearance-primary,_linear-gradient(_135deg,_var(--color-history-h-purple-13),_var(--color-history-h-pink-14)))] text-[var(--appearance-on-primary,_var(--color-history-color-21))] css-hover:text-[var(--appearance-on-primary,_var(--color-history-color-21))] border-[transparent] css-hover:border-[transparent]`
                : "",
          )}
          aria-label={
            pending
              ? replied
                ? "Undoing reply…"
                : "Saving…"
              : replied
                ? "Undo reply"
                : "Mark replied"
          }
          aria-disabled={
            pending ||
            (locked && access.reasons.markReplied !== "UPGRADE_REQUIRED")
          }
          aria-busy={pending}
          onClick={run}
        >
          {pending ? (
            <LoaderCircle
              size={16}
              aria-hidden="true"
              className="animate-spin motion-reduce:animate-none"
            />
          ) : (
            <Check size={16} aria-hidden="true" />
          )}
          {locked && (
            <span
              className="absolute right-[-4px] top-[-6px] text-[10px]"
              aria-hidden="true"
            >
              <Crown size={14} className="premium-icon" aria-hidden="true" />
            </span>
          )}
        </button>
      </Tooltip>
      {(pending || result) && (
        <p role="status" aria-live="polite" className="sr-only">
          {pending
            ? "Saving…"
            : result?.message.replace(/\bPaid\b/g, "Premium")}
        </p>
      )}
      {result?.ok === false && (
        <p role="alert" className="mt-2 text-xs text-error-deep">
          {result.message.replace(/\bPaid\b/g, "Premium")}
        </p>
      )}
    </div>
  );
}
function ShortlistAction({
  id,
  shortlist,
}: {
  id: string;
  shortlist: ShortlistState;
}) {
  const access = useWorkspaceEntitlements();
  const upgrade = usePremiumUpgrade();
  const locked = !access.features.historyShortlist;
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const busy = useRef(false);
  const router = useRouter();
  const disabled =
    (locked && access.reasons.historyShortlist !== "UPGRADE_REQUIRED") ||
    pending ||
    shortlist.inShortlist ||
    shortlist.blocked ||
    !shortlist.active;
  const label = shortlist.inShortlist
    ? "In shortlist"
    : pending
      ? "Adding…"
      : "Add to shortlist";
  function run() {
    if (disabled || busy.current) return;
    if (locked) return upgrade({ feature: "shortlist" });
    busy.current = true;
    start(async () => {
      try {
        setResult(await addToShortlist(id));
        router.refresh();
      } catch {
        setResult({
          ok: false,
          message: "Could not add this person. Try again.",
        });
      } finally {
        busy.current = false;
      }
    });
  }
  const explanation = shortlist.blocked
    ? "Pending delivery"
    : !shortlist.active
      ? "Contact unavailable"
      : shortlist.inShortlist
        ? "In shortlist"
        : "Add to shortlist to email this person again.";
  return (
    <div>
      <Tooltip
        className="history-surface"
        interactive={locked}
        content={
          locked ? (
            <PremiumTooltip
              actionDescription={
                shortlist.blocked || !shortlist.active || shortlist.inShortlist
                  ? explanation
                  : "Add from History with Premium. On Free, enter and save this person’s details in Contacts to email them again."
              }
            />
          ) : (
            explanation
          )
        }
      >
        <button
          type="button"
          className={cn(
            styles.action,
            "cursor-pointer grid place-items-center w-8.5 h-8.5 p-0 border border-solid border-[var(--appearance-border,_var(--color-history-border-color-18))] rounded-[50%] relative [background:transparent] text-[var(--h-text)] css-hover:[background:var(--appearance-wash,_var(--color-history-background-22))] [&[aria-disabled='true']]:opacity-[0.5] [&[aria-disabled='true']]:cursor-default",
            locked ? "border-dashed" : "",
          )}
          aria-label={label}
          aria-disabled={disabled}
          aria-busy={pending}
          onClick={run}
        >
          {shortlist.inShortlist ? (
            <Check size={16} aria-hidden="true" />
          ) : pending ? (
            <LoaderCircle
              size={16}
              aria-hidden="true"
              className="animate-spin motion-reduce:animate-none"
            />
          ) : (
            <Plus size={16} aria-hidden="true" />
          )}
          {locked && (
            <span
              className="absolute right-[-4px] top-[-6px] text-[10px]"
              aria-hidden="true"
            >
              <Crown size={14} className="premium-icon" aria-hidden="true" />
            </span>
          )}
        </button>
      </Tooltip>
      {result?.ok === false && (
        <p role="alert" className="mt-2 text-xs text-error-deep">
          {result.message.replace(/\bPaid\b/g, "Premium")}
        </p>
      )}
    </div>
  );
}
